const query = "how to make plain black screen clip CapCut desktop";
const res = await tool.fetch_url({
  url: `https://www.google.com/search?q=${encodeURIComponent(query)}&hl=en`,
  credentials: "omit"
});
console.log("Status:", res.status);
console.log("Length:", res.body?.length);
console.log("Has captcha:", res.body?.includes("recaptcha") || res.body?.includes("unusual traffic"));

// Let's parse links from the response body
const links = [];
const regex = /<a href="(\/url\?q=[^"&]+|https:\/\/[^"&]+)"[^>]*>(.*?)<\/a>/g;
let match;
while ((match = regex.exec(res.body)) !== null) {
  let url = match[1];
  if (url.startsWith("/url?q=")) {
    url = decodeURIComponent(url.slice(7));
  }
  const text = match[2].replace(/<[^>]+>/g, "").trim();
  if (url.startsWith("http") && !url.includes("google.com")) {
    links.push({ url, text });
  }
}
console.log("Found links count:", links.length);
console.log("First 10 links:", JSON.stringify(links.slice(0, 10), null, 2));

